public void modifiedField(FieldId _fieldId)
{
    next modifiedField(_fieldId);

    OMDepartmentRecId parentDepartmentUnit = 0;

    switch(_fieldId)
    {
        case fieldNum(HcmPositionDetail, NVDepartGroup2):
            if(this.NVDepartGroup2 == 0)
                break;

            if(this.NVDepartGroup1 != 0)
                break;

            parentDepartmentUnit = NVOMOperatingUnit_Events::getParentDepartment(this.NVDepartGroup2);
            if(parentDepartmentUnit != 0)
            {
                this.NVDepartGroup1 = parentDepartmentUnit;
            }

        case fieldNum(HcmPositionDetail, NVDepartGroup1):
            if(this.NVDepartGroup1 == 0)
                break;

            if(this.NVDepartDivision != 0)
                break;

            parentDepartmentUnit = NVOMOperatingUnit_Events::getParentDepartment(this.NVDepartGroup1);
            if(parentDepartmentUnit != 0)
            {
                this.NVDepartDivision = parentDepartmentUnit;
            }

        case fieldNum(HcmPositionDetail, NVDepartDivision):
            if(this.NVDepartDivision == 0)
                break;

            if(this.NVDepartDepartment != 0)
                break;

            parentDepartmentUnit = NVOMOperatingUnit_Events::getParentDepartment(this.NVDepartDivision);
            if(parentDepartmentUnit != 0)
            {
                this.NVDepartDepartment = parentDepartmentUnit;
            }

        case fieldNum(HcmPositionDetail, NVDepartDepartment):
            this.Department = this.NVDepartDepartment;
            if(this.NVDepartDepartment == 0)
                break;

            if(this.NVDepartBusinessUnit != 0)
                break;

            parentDepartmentUnit = NVOMOperatingUnit_Events::getParentDepartment(this.NVDepartDepartment);
            if(parentDepartmentUnit != 0)
            {
                this.NVDepartBusinessUnit = parentDepartmentUnit;
            }

        case fieldNum(HcmPositionDetail, NVDepartBusinessUnit):
            if(this.NVDepartBusinessUnit == 0)
                break;

            if(this.NVDepartLegalEntity != 0)
                break;

            parentDepartmentUnit = NVOMOperatingUnit_Events::getParentDepartment(this.NVDepartBusinessUnit);
            if(parentDepartmentUnit != 0)
            {
                this.NVDepartLegalEntity = parentDepartmentUnit;
            }
    }
}

public display Amount internalGradeMinAmount()
{
    NVHcmCompensationLevelPayroll levelPayroll = NVHcmCompensationLevelPayroll::findCurrent(this.NVInternalGrade);

    if(levelPayroll)
        return levelPayroll.MinSalary * this.getInternalGradeCoefficient();

    return 0;
}

public display Amount internalGradeMedAmount()
{
    NVHcmCompensationLevelPayroll levelPayroll = NVHcmCompensationLevelPayroll::findCurrent(this.NVInternalGrade);

    if(levelPayroll)
        return levelPayroll.MedSalary * this.getInternalGradeCoefficient();

    return 0;
}

public display Amount internalGradeMaxAmount()
{
    NVHcmCompensationLevelPayroll levelPayroll = NVHcmCompensationLevelPayroll::findCurrent(this.NVInternalGrade);

    if(levelPayroll)
        return levelPayroll.MaxSalary * this.getInternalGradeCoefficient();

    return 0;
}

private Amount getInternalGradeCoefficient()
{
    NVOMDepartmentGradeCoefficient gradeCoefficient;

    select gradeCoefficient
        where gradeCoefficient.InternalGrade == this.NVInternalGrade 
        && gradeCoefficient.Department == this.NVDepartDepartment;

    return gradeCoefficient.Coefficient;
}
